/**
 * Reopens the prepared store before each query so every sort starts with cold Java dictionary caches. Compare native
 * reader amortization with common-pool parallelism 1 and 8 in separate, otherwise identical JMH forks.
 */
@State(Scope.Thread)
@BenchmarkMode(Mode.AverageTime)
@OutputTimeUnit(TimeUnit.MILLISECONDS)
@Warmup(iterations = 3, time = 1)
@Measurement(iterations = 5, time = 1)
@Fork(value = 1, jvmArgs = { "-Xms1G", "-Xmx1G" })
public class ColdDictionaryOrderBenchmark {

	@Param({ "32768" })
	public int rows;

	private File directory;
	private SailRepository repository;

	@Setup(Level.Trial)
	public void prepareDictionary() throws Exception {
		directory = Files.createTempDirectory("lmdb-cold-dictionary-order-").toFile();
		openColdRepository();
		SimpleValueFactory vf = SimpleValueFactory.getInstance();
		IRI predicate = vf.createIRI("urn:cold-dictionary:predicate");
		try (SailRepositoryConnection connection = repository.getConnection()) {
			connection.begin(IsolationLevels.NONE);
			for (int i = 0; i < rows; i++) {
				int mixed = (i * 8191) & (rows - 1);
				String label = String.format("dictionary-label-%08d", mixed);
				connection.add(vf.createIRI("urn:cold-dictionary:subject:" + i), predicate,
						vf.createLiteral(label, vf.createIRI("urn:cold-dictionary:datatype:" + (i & 7))));
			}
			connection.commit();
		} finally {
			repository.shutDown();
			repository = null;
		}
	}

	@Setup(Level.Invocation)
	public void openColdRepository() {
		LmdbStore store = new LmdbStore(directory, new LmdbStoreConfig("spoc,posc").setInlineLiterals(false));
		// Exercise the repository's model comparator and its context-aware ORDER BY workers.
		store.setEvaluationStrategyFactory(new DefaultEvaluationStrategyFactory());
		repository = new SailRepository(store);
		repository.init();
	}

	@Benchmark
	public long orderByDictionaryValues() {
		long count = 0;
		try (SailRepositoryConnection connection = repository.getConnection()) {
			connection.begin(IsolationLevels.SNAPSHOT);
			try (TupleQueryResult result = connection.prepareTupleQuery(
					"SELECT ?value ?s WHERE { ?s <urn:cold-dictionary:predicate> ?value } ORDER BY ?value ?s")
					.evaluate()) {
				while (result.hasNext()) {
					result.next();
					count++;
				}
			}
			connection.rollback();
		}
		if (count != rows) {
			throw new IllegalStateException("Unexpected ORDER BY cardinality: " + count);
		}
		return count;
	}

	@TearDown(Level.Invocation)
	public void closeRepository() {
		if (repository != null) {
			repository.shutDown();
			repository = null;
		}
	}

	@TearDown(Level.Trial)
	public void removePreparedStore() throws Exception {
		closeRepository();
		LmdbTestUtil.deleteDir(directory);
	}
}
